suppressPackageStartupMessages(library(data.table))
a<-commandArgs(FALSE);out<-dirname(normalizePath(sub('^--file=','',a[grepl('^--file=',a)][1])))
root<-normalizePath(file.path(out,'../../..'))
p<-file.path(root,'2026-09-08_fresh_audit/work/feronia-cell-type-specific/scripts_and_inputs/Analysis/CellOracle_GRN_analysis/outputs')
scorepaths<-list.files(p,pattern='_gene_score_iGRN.csv$',full.names=TRUE)
scores<-rbindlist(lapply(scorepaths,function(f){s<-fread(f);setnames(s,names(s)[1],'gene');s[,tissue:=sub('_rawRNA.*','',basename(f))];s}),fill=TRUE)
metrics<-setdiff(names(scores),c('gene','name','cluster','tissue'))
allclusters<-unique(scores$cluster)
bad<-c('Maturation_Endodermis_fer4_untreated','Proliferation Domain_Endodermis_fer4_untreated','Transition Domain_Endodermis_fer4_untreated')
comparisons<-rbindlist(lapply(bad,function(b){x<-copy(scores[cluster==b]);setorder(x,gene);rbindlist(lapply(setdiff(allclusters,b),function(k){y<-copy(scores[cluster==k]);setorder(y,gene);samegenes<-identical(x$gene,y$gene);sameout<-samegenes&&isTRUE(all.equal(x$degree_out,y$degree_out,tolerance=1e-12));samemetrics<-samegenes&&isTRUE(all.equal(as.data.frame(x[,..metrics]),as.data.frame(y[,..metrics]),tolerance=1e-12,check.attributes=FALSE));data.table(affected_cluster=b,comparison_cluster=k,n_affected=nrow(x),n_comparison=nrow(y),identical_genes=samegenes,identical_outdegree=sameout,identical_all_numeric_columns=samemetrics)}))}))
fwrite(comparisons,file.path(out,'cross_context_score_identity.csv'))
print(comparisons[identical_genes|identical_outdegree|identical_all_numeric_columns])
e<-fread(file.path(p,'endodermis_rawRNA_celloracle_network_iGRN.csv'))
s<-scores[tissue=='endodermis'];deg<-e[,.(edge_out=.N),by=.(cluster,gene=source)]
comp<-merge(s[,.(gene,name,cluster,degree_out,degree_centrality_out)],deg,by=c('gene','cluster'),all=TRUE)
comp[is.na(edge_out),edge_out:=0L]
fwrite(comp,file.path(out,'endodermis_gene_degree_comparison.csv'))
summary<-merge(e[,.(edge_rows=.N,edge_nodes=uniqueN(c(source,target)),duplicate_pairs=sum(duplicated(paste(source,target))),self_edges=sum(source==target)),by=cluster],s[,.(score_genes=.N,sum_stored_degree_out=sum(degree_out)),by=cluster],by='cluster')
fwrite(summary,file.path(out,'endodermis_graph_summary.csv'));print(summary)
dof<-fread(file.path(root,'2026-09-20_dof_subnetworks/inventory/tested10_identities.csv'))
examples<-comp[gene%in%dof$gene][dof,on='gene'];fwrite(examples,file.path(out,'tested10_endodermis_degree_comparison.csv'))
